#include <SDL.h>
#include <d3d9.h>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
static void check(bool ok,const char*m){if(!ok){fprintf(stderr,"FAIL: %s\n",m);exit(1);}}
int main(){
 setenv("STORM_METAL_PROFILE","1",1);check(SDL_Init(SDL_INIT_VIDEO)==0,SDL_GetError());auto*w=SDL_CreateWindow("FFP cache fixture",0,0,64,64,SDL_WINDOW_HIDDEN|SDL_WINDOW_METAL);check(w,SDL_GetError());auto*api=Direct3DCreate9(D3D_SDK_VERSION);D3DPRESENT_PARAMETERS pp{};pp.BackBufferWidth=pp.BackBufferHeight=64;pp.BackBufferCount=1;pp.BackBufferFormat=D3DFMT_A8R8G8B8;pp.Windowed=TRUE;pp.hDeviceWindow=w;pp.SwapEffect=D3DSWAPEFFECT_DISCARD;IDirect3DDevice9*d=nullptr;check(SUCCEEDED(api->CreateDevice(0,D3DDEVTYPE_HAL,w,0,&pp,&d)),"device");
 struct V{float x,y,z,nx,ny,nz;DWORD color;};V v[]={{-.8f,-.8f,.5f,0,0,-1,0xffff2020},{.8f,-.8f,.5f,0,0,-1,0xff20ff20},{-.8f,.8f,.5f,0,0,-1,0xff2020ff},{.8f,.8f,.5f,0,0,-1,0xffeeeeee}};uint16_t ix[]={0,1,2,2,1,3};
 d->SetFVF(D3DFVF_XYZ|D3DFVF_NORMAL|D3DFVF_DIFFUSE);d->SetRenderState(D3DRS_ZENABLE,FALSE);d->SetRenderState(D3DRS_LIGHTING,FALSE);d->SetRenderState(D3DRS_CULLMODE,D3DCULL_NONE);d->SetTextureStageState(0,D3DTSS_COLOROP,D3DTOP_SELECTARG1);d->SetTextureStageState(0,D3DTSS_COLORARG1,D3DTA_DIFFUSE);d->SetTextureStageState(1,D3DTSS_COLOROP,D3DTOP_DISABLE);
 IDirect3DVertexBuffer9*vb=nullptr;IDirect3DIndexBuffer9*ib=nullptr;d->CreateVertexBuffer(sizeof(v),0,0,D3DPOOL_MANAGED,&vb,nullptr);d->CreateIndexBuffer(sizeof(ix),0,D3DFMT_INDEX16,D3DPOOL_MANAGED,&ib,nullptr);void*p=nullptr;
 auto uploadVB=[&](){check(SUCCEEDED(vb->Lock(0,0,&p,0)),"VB lock");memcpy(p,v,sizeof(v));check(SUCCEEDED(vb->Unlock()),"VB unlock");};auto uploadIB=[&](){check(SUCCEEDED(ib->Lock(0,0,&p,0)),"IB lock");memcpy(p,ix,sizeof(ix));check(SUCCEEDED(ib->Unlock()),"IB unlock");};uploadVB();uploadIB();
 IDirect3DSurface9*target=nullptr,*readback=nullptr;d->GetRenderTarget(0,&target);d->CreateOffscreenPlainSurface(64,64,D3DFMT_A8R8G8B8,D3DPOOL_SYSTEMMEM,&readback,nullptr);
 auto render=[&](bool bound){d->Clear(0,nullptr,D3DCLEAR_TARGET,0xff102030,1,0);d->BeginScene();if(bound){d->SetStreamSource(0,vb,0,sizeof(V));d->SetIndices(ib);check(SUCCEEDED(d->DrawIndexedPrimitive(D3DPT_TRIANGLELIST,0,0,4,0,2)),"bound draw");}else{V expanded[6];for(int i=0;i<6;i++)expanded[i]=v[ix[i]];check(SUCCEEDED(d->DrawPrimitiveUP(D3DPT_TRIANGLELIST,2,expanded,sizeof(V))),"UP reference");}d->EndScene();check(SUCCEEDED(d->GetRenderTargetData(target,readback)),"readback");D3DLOCKED_RECT r{};check(SUCCEEDED(readback->LockRect(&r,nullptr,D3DLOCK_READONLY)),"readback lock");std::vector<DWORD> out(4096);for(int y=0;y<64;y++)memcpy(out.data()+64*y,(char*)r.pBits+y*r.Pitch,256);readback->UnlockRect();return out;};
 auto verify=[&](const char*why){auto reference=render(false);check(render(true)==reference,why);check(render(true)==reference,"repeat cache hit matches reference");};
 verify("initial source");D3DMATRIX matrix{};for(int i=0;i<4;i++)matrix.m[i][i]=1;matrix.m[3][0]=.18f;d->SetTransform(D3DTS_VIEW,&matrix);verify("view remains per draw");matrix.m[0][0]=.65f;matrix.m[3][0]=0;d->SetTransform(D3DTS_PROJECTION,&matrix);verify("projection remains per draw");
 v[0].color=0xff00ffff;v[1].x=.3f;uploadVB();verify("same-frame VB mutation");ix[3]=0;ix[4]=2;ix[5]=3;uploadIB();verify("same-frame IB mutation");
 check(SUCCEEDED(vb->Lock(0,0,&p,0)),"locked bypass");v[2].color=0xffffff00;memcpy(p,v,sizeof(v));verify("locked VB bypasses cached revision");v[2].color=0xffff00ff;memcpy(p,v,sizeof(v));verify("second locked edit bypasses cache");vb->Unlock();verify("unlock revision");
 check(SUCCEEDED(ib->Lock(0,0,&p,0)),"locked IB bypass");ix[0]=3;memcpy(p,ix,sizeof(ix));verify("locked IB content changes");ib->Unlock();
 check(SUCCEEDED(d->Present(nullptr,nullptr,nullptr,nullptr)),"present");verify("next frame arena reuse");
 target->Release();target=nullptr;check(SUCCEEDED(d->Reset(&pp)),"reset");d->GetRenderTarget(0,&target);d->SetFVF(D3DFVF_XYZ|D3DFVF_NORMAL|D3DFVF_DIFFUSE);d->SetRenderState(D3DRS_ZENABLE,FALSE);d->SetRenderState(D3DRS_CULLMODE,D3DCULL_NONE);d->SetTextureStageState(0,D3DTSS_COLOROP,D3DTOP_SELECTARG1);d->SetTextureStageState(0,D3DTSS_COLORARG1,D3DTA_DIFFUSE);verify("reset cache invalidation");
 d->SetRenderState(D3DRS_LIGHTING,TRUE);D3DMATERIAL9 material{};material.Diffuse={.7f,.6f,.5f,1};material.Ambient={.2f,.2f,.2f,1};d->SetMaterial(&material);d->SetRenderState(D3DRS_AMBIENT,0xff404040);D3DLIGHT9 light{};light.Type=D3DLIGHT_DIRECTIONAL;light.Direction={0,0,1};light.Diffuse={.8f,.7f,.6f,1};d->SetLight(0,&light);d->LightEnable(0,TRUE);verify("lit cache baseline");
 D3DLIGHT9 stabilizedSun{};d->GetLight(0,&stabilizedSun);light.Direction.x=.00001f;d->SetLight(0,&light);D3DLIGHT9 nearbySun{};d->GetLight(0,&nearbySun);check(memcmp(&stabilizedSun.Direction,&nearbySun.Direction,sizeof(D3DVECTOR))==0,"subtexel sun motion shares the light and shadow source");verify("stabilized sun pixels");d->SetLight(1,&light);D3DLIGHT9 secondary{};d->GetLight(1,&secondary);check(memcmp(&secondary.Direction,&light.Direction,sizeof(D3DVECTOR))==0,"other directional lights retain original direction");
 matrix={};for(int i=0;i<4;i++)matrix.m[i][i]=1;matrix.m[3][0]=.125f;d->SetTransform(D3DTS_WORLD,&matrix);light.Position={.125f,0,0};d->SetLight(0,&light);verify("camera-relative sun cache pixels");light.Direction={1,0,1};d->SetLight(0,&light);verify("sun direction invalidates cached colors");
 light.Type=D3DLIGHT_POINT;light.Position={0,0,-1};light.Range=10;light.Attenuation0=1;light.Attenuation1=.5f;d->SetLight(0,&light);verify("point light baseline");matrix.m[3][0]=.3f;d->SetTransform(D3DTS_WORLD,&matrix);verify("point light world position invalidation");light.Position.x=.6f;d->SetLight(0,&light);verify("point light position invalidation");
 IDirect3DVertexBuffer9*dynamicVB=nullptr;check(SUCCEEDED(d->CreateVertexBuffer(sizeof(v),D3DUSAGE_DYNAMIC|D3DUSAGE_WRITEONLY,D3DFVF_XYZ|D3DFVF_NORMAL|D3DFVF_DIFFUSE,D3DPOOL_DEFAULT,&dynamicVB,nullptr)),"dynamic VB");D3DVERTEXBUFFER_DESC dynamicDesc{};check(SUCCEEDED(dynamicVB->GetDesc(&dynamicDesc))&&(dynamicDesc.Usage&D3DUSAGE_DYNAMIC)&&dynamicDesc.FVF==(D3DFVF_XYZ|D3DFVF_NORMAL|D3DFVF_DIFFUSE),"dynamic source metadata reaches cache admission");vb->Release();vb=dynamicVB;uploadVB();verify("dynamic source uses frame arena");v[0].x+=.05f;uploadVB();verify("dynamic source revision pixels");IDirect3DIndexBuffer9*dynamicIB=nullptr;check(SUCCEEDED(d->CreateIndexBuffer(sizeof(ix),D3DUSAGE_DYNAMIC,D3DFMT_INDEX16,D3DPOOL_DEFAULT,&dynamicIB,nullptr)),"dynamic IB");D3DINDEXBUFFER_DESC indexDesc{};check(SUCCEEDED(dynamicIB->GetDesc(&indexDesc))&&(indexDesc.Usage&D3DUSAGE_DYNAMIC),"dynamic index metadata reaches cache admission");dynamicIB->Release();
 puts("PASS: FFP cache pixels match UP across lit/unlit camera, light, VB/IB and locked mutations, Present and Reset");target->Release();readback->Release();vb->Release();ib->Release();d->Release();api->Release();SDL_DestroyWindow(w);SDL_Quit();
}
